func toPBTrainsUK1(v *ds.TrainsUK1) *pb.TrainsUK1 {
	if v == nil {
		return nil
	}
	m := &pb.TrainsUK1{}
	if len(v.Rows) > 0 {
		m.Rows = make([]*pb.TrainsUK1Row, len(v.Rows))
		for i := range v.Rows {
			m.Rows[i] = toPBTrainsUK1Row(&v.Rows[i])
		}
	}
	return m
}

