func toPBUSCensus(v *ds.USCensus) *pb.USCensus {
	if v == nil {
		return nil
	}
	m := &pb.USCensus{}
	if len(v.Rows) > 0 {
		m.Rows = make([]*pb.USCensusRow, len(v.Rows))
		for i := range v.Rows {
			m.Rows[i] = toPBUSCensusRow(&v.Rows[i])
		}
	}
	return m
}

func fromPBUSCensus(m *pb.USCensus, v *ds.USCensus) {
	if m == nil {
		*v = ds.USCensus{}
		return
	}
	v.Rows = nil
	if len(m.Rows) > 0 {
		v.Rows = make([]ds.USCensusRow, len(m.Rows))
		for i, x := range m.Rows {
			fromPBUSCensusRow(x, &v.Rows[i])
		}
	}
}

