func toPBWins(v *ds.Wins) *pb.Wins {
	if v == nil {
		return nil
	}
	m := &pb.Wins{}
	if len(v.Rows) > 0 {
		m.Rows = make([]*pb.WinsRow, len(v.Rows))
		for i := range v.Rows {
			m.Rows[i] = toPBWinsRow(&v.Rows[i])
		}
	}
	return m
}

func fromPBWins(m *pb.Wins, v *ds.Wins) {
	if m == nil {
		*v = ds.Wins{}
		return
	}
	v.Rows = nil
	if len(m.Rows) > 0 {
		v.Rows = make([]ds.WinsRow, len(m.Rows))
		for i, x := range m.Rows {
			fromPBWinsRow(x, &v.Rows[i])
		}
	}
}

